function cloneIds(obj){const copy=JSON.parse(JSON.stringify(obj));const walk=v=>{if(!v||typeof v!=='object')return;if(Array.isArray(v)){v.forEach(walk);return}for(const [k,x] of Object.entries(v)){if(k==='id')v[k]=id();else if(k!=='catalogId'&&k!=='corpId'&&k!=='transportId'&&k!=='tractorId'&&k!=='scoutSource')walk(x)}};walk(copy);return copy}
function airCategory(x){let t=[x.name,x.subtype,x.type,x.traits,x.weapon].join(' ').toLowerCase();if(/bombardier|bomber|heinkel he 111|he 111|ju 88|pe-8|tb-3|il-4|db-3|b-17|b-24|tu-2/.test(t))return 'Bombardier';if(/attaque|assaut|stuka|ju 87|il-2|il-10|hs 129|strike|chasseur-bombardier|fighter.bomber|fw 190 f|su-2|pe-2/.test(t))return 'Attaque';return 'Chasse'}
