function modelPrice(f,m){let x=item(m.catalogId);if(!x)return null;let base=m.customPrice!=null?Number(m.customPrice):x.costs?.[state.period];if(base==null||!Number.isFinite(base))return null;let extras=(m.options||[]).reduce((n,k)=>n+(!['Zimmerit','Optique IR','Stabilisateur'].includes(k)||!allowedVehicleOption(x,k)||equipmentIncluded(x,k)?0:(k==='Zimmerit'?2:(B.vehicleOptions[k]??B.gunOptions[k]??0))),0);if(m.chenilles&&state.front==='EST'&&canAdaptTracks(x))extras+=B.vehicleOptions['Chenilles adaptées']||5;if(x.id==='universal-motos')extras+=({standard:3,mmg:5,hmg:7}[m.sidecar]||0);extras+=engineerCargoPrice(m,x);extras+=armorExtraPrice(m,x);let droneCost=deEngineerDronePrice(f,m,x);if(droneCost==null)return null;extras+=droneCost;let p=adjust(base+extras,m.exp||f.exp,m.morale||f.morale,m.osc??f.osc,m.fan??f.fan);if(m.escort&&escortAllowed(f)){let ep=escortPrice(f,m);if(ep!=null)p+=ep}if(m.tractorId){let t=item(m.tractorId);if(t){if(t.costs[state.period]==null)return null;p+=t.costs[state.period]}}return p}
function formationPrice(f){let n=baseFormation(f);if(isInf(f)){let base=infantryFormationPrice(f);if(!deG2(f))return base;let extra=deG2SupportPrice(f);return base==null||extra==null?null:base+extra;}if(f.kind==='offtable')return artilleryOfftablePrice(f);for(let u of f.units){let p=unitPrice(f,u);if(p==null)return null;n+=p}for(let m of f.models){let p=modelPrice(f,m);if(p==null)return null;n+=p}if(!['light','medium','heavy','recon','assault','td','air','transport'].includes(f.kind))for(let s of f.support)n+=B.support[s]||0;if(f.obs)n+=B.support['Observateur supplémentaire']||15;if(f.obsTransportId){let tp=transportPrice(f.obsTransportId,f.obsSidecar);if(tp==null)return null;n+=tp}for(let k of f.forts)n+=B.fortifications[k]||0;return n}
