function roleMatches(x,kind){const keys=[x.roleKey,...(Array.isArray(x.roleKeys)?x.roleKeys:[])].filter(Boolean);const raw=[x.role,x.subtype,x.type].join(' ').toLowerCase();return keys.includes(kind)||(kind==='art'&&isSu76MultiRole(x))||(kind==='at'&&/antichar|anti.char/.test(raw))||(kind==='aa'&&/antia[eé]rien|anti.a[eé]rien/.test(raw))}
// V0.8.9 : familles de chassis et mélanges explicitement autorisés par l'OdB Word.
function deTankFamily(x){let n=String(x?.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(/panzer\s*(?:ii|2)\b/.test(n))return 'panzer-ii';if(/panzer\s*(?:iii|3)\b/.test(n))return 'panzer-iii';if(/panzer\s*(?:iv|4)\b/.test(n))return 'panzer-iv';if(/panzer\s*(?:i|1)\b/.test(n))return 'panzer-i';if(/panzer\s*38\s*\(t\)/.test(n))return 'panzer-38t';if(/tiger\s*ii|tigre\s*ii/.test(n))return 'tiger-ii';if(/tiger\s*i\b|tigre\s*i\b/.test(n))return 'tiger-i';if(/stug\s*iii/.test(n))return 'stug-iii';if(/stug\s*iv/.test(n))return 'stug-iv';if(/stuh\s*42|stuh/.test(n))return 'stuh';if(/panther/.test(n))return 'panther';if(/hetzer/.test(n))return 'hetzer';if(/brummbar|brummb[aä]r/.test(n))return 'brummbar';if(/t-?34/.test(n))return 't34';if(/kv\s*-?\s*1/.test(n))return 'kv1';return n.replace(/\b(ausf|mod|version|variante)\b.*$/,'').replace(/\s*\([^)]*\)/g,'').replace(/\s+/g,' ').trim()}
