function deHeavyEscortCandidates(f){if(corps(f.corpId)?.nation!=='Allemagne'||f.kind!=='heavy')return [];return all().filter(x=>x.nation==='Allemagne'&&x.kind==='armor'&&deTankFamily(x)==='panzer-iii'&&/\b(?:L|M|N)\b/i.test(x.name)&&available(x,corps(f.corpId))&&state.year>=1942&&state.year<=1943&&deMainModels(f).some(m=>deTankFamily(item(m.catalogId))==='tiger-i'));}
