function tractorRank(x){return TRACTOR_RANK[String(x?.tractorClass||'').toLowerCase()]||0}
function gunRank(x){return TRACTOR_RANK[String(x?.weight||'').toLowerCase()]||0}
function tractorCompatible(g,t,c){return !!(g&&t&&g.kind==='gun'&&g.mounting==='tracté'&&t.kind==='transport'&&gunRank(g)&&tractorRank(t)>=gunRank(g)&&available(t,c))}
function tractorChoices(g,c){return all().filter(t=>tractorCompatible(g,t,c))}
function transportCapacity(x){if(!x)return null;const txt=[x.constant,x.traits].join(' ; ');const match=txt.match(/Transport\s*\(\s*(\d+)\s*(?:\+\s*(?:Support|St))?\s*\)/i);return match?Number(match[1]):null}
function transportCanCarrySupport(x){return /Transport\s*\(\s*\d+\s*\+\s*(?:Support|St)\s*\)/i.test([x?.constant,x?.traits].join(' ; '))}
function transportCheck(f,tid,needed,supportCount,label,count=1){if(!tid)return [];let x=item(tid),c=corps(f.corpId),a=[];if(!x||x.kind!=='transport'||!available(x,c))return [label+' : transport indisponible ou interdit.'];let cap=transportCapacity(x);if(x.id==='universal-motos')cap=1;if(cap==null)a.push(label+' : capacité de transport non renseignée dans l’OdB (à vérifier).');else if(needed>cap*Math.max(1,Number(count)||1))a.push(label+' : '+needed+' unités pour '+(cap*Math.max(1,Number(count)||1))+' places (« '+x.name+' » × '+count+').');if(supportCount>0&&!transportCanCarrySupport(x))a.push(label+' : transport sans capacité Support explicitement indiquée.');return a}
function formationIssues(f){let a=[],c=corps(f.corpId),l=limits(f);a.push(...deG2Issues(f));if(c?.nation==='Allemagne'&&['inf','reserve','genie','cav','scout','horseScout'].includes(f.kind)){let spec=DE_INF_FORMATIONS.find(x=>x.name===f.germanOdbFormation);if(!spec)a.push('Formation absente de la liste nominative de l’OdB allemand : recréer avec le sélecteur OdB');else if(state.year<spec.from||state.year>deEnd(spec.to))a.push('Formation indisponible en '+state.year+' selon l’OdB allemand ('+spec.from+'–'+spec.to+')');if(spec?.name.includes('Pionniers')&&f.dePioneerMode==='attached'&&!deHostOptions(f).some(x=>x.id===f.deHost))a.push('Section de Pionniers : formation hôte obligatoire');if(spec?.name.includes('Volkstürm')&&state.front!=='OUEST')a.push('Volkstürm : front OUEST uniquement');}if(l&&deMainModels(f).length&&(deMainModels(f).length<l[0]||deMainModels(f).length>l[1]))a.push('Effectif '+deMainModels(f).length+' hors limites '+l[0]+'–'+l[1]);if(isGun(f)){for(let m of f.models){let g=item(m.catalogId);if(!g||!available(g,c)||!roleMatches(g,f.kind))a.push('Canon incompatible avec cette formation : '+(g?.name||m.catalogId));if(g?.mounting==='tracté'){if(m.tractorId&&!tractorCompatible(g,item(m.tractorId),c))a.push('Tracteur incompatible avec '+g.name);if(!m.tractorId)a.push('Tracteur non sélectionné pour '+g.name+' (mobilité à vérifier)')}else if(m.tractorId)a.push('Tracteur affecté à une pièce non tractée')}}
if(c?.nation==='Allemagne'&&['light','medium','heavy','assault','td','recon'].includes(f.kind)){let mains=deMainModels(f);for(let i=1;i<mains.length;i++){let test={...f,models:mains.slice(0,i)};if(!deMixAllowed(test,item(mains[i].catalogId)))a.push('Mélange de modèles non autorisé par la structure OdB Word : '+(item(mains[i].catalogId)?.name||'?'));}for(const m of f.models){let x=item(m.catalogId);if(m.deHeavyEscort&&(f.kind!=='heavy'||deTankFamily(x)!=='panzer-iii'||state.year<1942||state.year>1943||!mains.some(z=>deTankFamily(item(z.catalogId))==='tiger-i')))a.push('Escorte Panzer III incompatible (Tigre I, 1942–1943)');if(m.deHeavyEscort&&f.models.filter(z=>z.deHeavyEscort).length>3)a.push('Maximum 3 Panzer III d’escorte');if(m.deDrone&&!deEngineerCarrier(f,x))a.push('Goliath/Borgward : uniquement formation de génie Tigre I ou StuG');}}
if(f.kind==='recon'&&f.models.some(m=>!item(m.catalogId)?.recon))a.push('Référence non Reco dans la formation');
if(isInf(f)){normalizeFormation(f);if(f.kind!=='sniper'){for(let [i,sec] of (f.sections||[]).entries()){let min=['scout','horseScout'].includes(f.kind)?2:3,max=4;if(sec.units.length<min||sec.units.length>max)a.push('Section '+(i+1)+' : effectif '+sec.units.length+' hors '+min+'–'+max);if(panzerfaustInSection(sec)>panzerfaustLimit(f))a.push('Section '+(i+1)+' : trop de Panzerfaust');a.push(...transportCheck(f,sec.transportId,sec.units.length,(sec.support||[]).length,'Section '+(i+1),sec.transportCount||1))}}if(!['scout','horseScout','sniper'].includes(f.kind))a.push(...transportCheck(f,f.hq.transportId,1,(f.support||[]).length,'QG',f.hq.transportCount||1));if(!f.engineer&&(f.sections||[]).filter(sec=>sec.genie).length>1)a.push('Plusieurs sections Génie sélectionnées');}
for(let m of f.models){let x=item(m.catalogId);if(!x||!available(x,c))a.push('Référence indisponible : '+(x?.name||m.catalogId));if(m.tractorId&&x?.mounting!=='tracté')a.push('Tracteur sur unité non tractée');}
return a}
function canDuplicateModel(f){let l=limits(f);return !l||deMainModels(f).length<l[1]}
function limits(f){let sov=corps(f.corpId)?.nation==='URSS';if(['light','medium','assault','td'].includes(f.kind))return sov?[2,10]:[2,5];if(f.kind==='heavy')return sov?[2,5]:[1,3];if(f.kind==='recon'){let first=f.models[0]&&item(f.models[0].catalogId);return first?.kind==='armor'?[1,5]:[1,3]}if(isGun(f)){let first=f.models[0]&&item(f.models[0].catalogId);let weight=first?.weight||'moyen',mount=first?.mounting||'tracté';return weight==='lourd'?[1,3]:mount!=='tracté'?[2,4]:weight==='léger'?[2,6]:[2,4]}return null}
function parseLimit(s){if(!s)return [0,Infinity];if(s.endsWith('+'))return [Number(s.slice(0,-1)),Infinity];if(s.includes('-'))return s.split('-').map(Number);return [Number(s),Number(s)]}
function deG4Audit(){
 const errors=[], warnings=[], info=[];
 for(const c of state.corps){
  const rare=c.formations.filter(f=>rarity(f)>0);
  if(rare.length>3)errors.push(c.nation+' : plus de 3 formations rares');
  if(rare.filter(f=>rarity(f)>=2).length>2)errors.push(c.nation+' : plus de 2 formations très rares');
  if(rare.filter(f=>rarity(f)>=3).length>1)errors.push(c.nation+' : plus de 1 prototype');
  for(const f of c.formations){
   const sp=c.nation==='Allemagne'?deSpec(f):null;
   if(sp){
    if(state.year<sp.from||state.year>deEnd(sp.to))errors.push(f.name+' : hors période OdB ('+sp.from+'–'+deEnd(sp.to)+')');
    if(sp.west&&state.front!=='OUEST')errors.push(f.name+' : front Ouest obligatoire');
    if(sp.reduce&&f.size==='reduite'&&state.year<sp.reduce)errors.push(f.name+' : compagnie réduite non autorisée avant '+sp.reduce);
    if(sp.reduce&&f.sections.length!== (f.size==='reduite'?2:3)&&f.dePioneerMode!=='attached')errors.push(f.name+' : nombre de sections incompatible avec la structure');
    if(sp.name.includes('Pionniers')&&f.dePioneerMode==='attached'&&!deHostOptions(f).some(h=>h.id===f.deHost))errors.push(f.name+' : formation hôte obligatoire');
    if(sp.name.includes('Volkstürm')){
     const host=c.formations.find(h=>h.id===f.deHost);
     if(!host||!['inf','genie'].includes(host.kind))errors.push(f.name+' : renfort sans formation d’infanterie hôte');
    }
    if(sp.name.includes('Panzergrenadiers')&&f.sections.filter(x=>x.genie).length>1)errors.push(f.name+' : plus d’une section de Pionniers');
    if(sp.name.includes('Volksgrenadiers')&&f.sections.filter(x=>x.type==='Ligne').length>1)errors.push(f.name+' : plus d’une section de Ligne');
   }
   for(const t of formationIssues(f)){
    if(/capacité de transport non renseignée|mobilité à vérifier|ancien support|à migrer/i.test(t))warnings.push(f.name+' : '+t);
    else errors.push(f.name+' : '+t);
   }
   if(formationPrice(f)==null)errors.push(f.name+' : tarif à confirmer, total non définitif');
  }
 }
 if(state.year>=1946&&state.year<=1947)info.push('Prolongation validée : les disponibilités allemandes de 1945 restent applicables jusqu’en 1947.');
 return {errors:[...new Set(errors)],warnings:[...new Set(warnings)],info};
}
function deG4Markup(){const a=deG4Audit();return `<section class="panel"><h2>Conformité V0.8.8</h2><p class="muted">${a.errors.length} erreur(s) · ${a.warnings.length} avertissement(s) · ${a.info.length} information(s). Les listes importées sont conservées sans suppression automatique.</p>${a.errors.map(t=>`<p class="warning">⛔ Erreur : ${E(t)}</p>`).join('')}${a.warnings.map(t=>`<p class="warning">⚠ Avertissement : ${E(t)}</p>`).join('')}${a.info.map(t=>`<p class="muted">ℹ ${E(t)}</p>`).join('')}${!a.errors.length?'<p class="good">Aucune erreur détectée par les contrôles structurés.</p>':''}</section>`}
function migrationReport(s){let unknown=[],invalid=[];for(const c of s.corps||[])for(const f of c.formations||[]){if(c.nation==='Allemagne'&&['inf','reserve','genie','cav','scout','horseScout'].includes(f.kind)&&!deSpec(f))unknown.push(f.name);for(const m of f.models||[])if(!item(m.catalogId))unknown.push(m.catalogId)}return {unknown:[...new Set(unknown)],version:s.schemaVersion||'ancienne',count:(s.corps||[]).reduce((n,c)=>n+(c.formations||[]).length,0)}}
function warnings(){let a=[],forms=state.corps.flatMap(c=>c.formations);for(const c of state.corps){const rares=c.formations.filter(f=>rarity(f)>0);if(rares.length>3)a.push(`${c.nation} : ${rares.length} formations rares (maximum 3 par corps).`);if(rares.filter(f=>rarity(f)>=2).length>2)a.push(`${c.nation} : plus de 2 formations ** ou ***.`);if(rares.filter(f=>rarity(f)>=3).length>1)a.push(`${c.nation} : plus d’une formation ***.`);}let grand=0;for(let c of state.corps){let total=0;let counts={};for(let f of c.formations){counts[f.kind]=(counts[f.kind]||0)+1;for(const issue of formationIssues(f))a.push(`${f.name} : ${issue}.`);if(f.kind==='cav')counts.light=(counts.light||0)+1;let p=formationPrice(f);if(p==null)a.push(`${f.name} : budget manquant dans l’OdB.`);else total+=p;let l=limits(f);if(l&&deMainModels(f).length&&(deMainModels(f).length<l[0]||deMainModels(f).length>l[1]))a.push(`${f.name} : ${f.models.length} pièce(s), limites indicatives ${l[0]}–${l[1]}.`);if(isInf(f))for(const [si,sec] of (f.sections||[]).entries())if(panzerfaustInSection(sec)>panzerfaustLimit(f))a.push(`${f.name} / section ${si+1} : ${panzerfaustInSection(sec)} Panzerfaust (maximum ${panzerfaustLimit(f)} par section).`);if(f.kind==='sniper'&&c.nation!=='URSS')a.push('Section de snipers : URSS uniquement.');if(f.kind==='recon'&&f.models.some(m=>{const x=item(m.catalogId);return !x?.recon||x.kind==='air'}))a.push(`${f.name} : unité incompatible avec la reconnaissance terrestre (avions à placer en support aérien).`)}let d=DOC[c.doctrine]||DOC[0];for(let [k,v] of Object.entries(d.limits)){let [min,max]=parseLimit(v),n=counts[k]||0;if(n<min||n>max)a.push(`${c.nation} / ${d.name} : ${KINDS[k]||k} ${n}, requis ${v}.`)}if(c===state.corps[0])grand=total;else if(total>state.budget/2)a.push('Le corps auxiliaire dépasse 50 % du budget total.')}if(state.corps.length>1&&grand<state.budget/2)a.push('Le corps principal est inférieur à 50 % du budget de référence.');let total=forms.reduce((n,f)=>n+(formationPrice(f)||0),0);if(total>state.budget)a.push(`Budget dépassé de ${money(total-state.budget)}.`);return a}
function summary(){let forms=state.corps.flatMap(c=>c.formations),cost=forms.reduce((n,f)=>n+(formationPrice(f)||0),0),fort=state.independentForts.reduce((n,k)=>n+(B.fortifications[k]||0),0),rare=forms.filter(f=>rarity(f));return `<div class="stats"><div><small>Armée</small><b>${money(cost)} / ${money(state.budget)}</b></div><div><small>Formations</small><b>${forms.length}</b></div><div><small>Rareté (total des corps)</small><b>${rare.length} · ** ${rare.filter(f=>rarity(f)>=2).length} · *** ${rare.filter(f=>rarity(f)>=3).length}</b></div><div><small>Fortifications indépendantes</small><b>${money(fort)} / ${money(state.fortBudget)}</b></div></div>`}
function header(){return `<header><div><h1>IRON TIDE</h1><p>12–20mm WW2 Wargame · GitHub V0.9.0 · Groupes 1–4 · Allemagne / URSS</p></div><nav><button data-action="tab" data-value="army" class="${view==='army'?'active':''}">Armée</button><button data-action="tab" data-value="fort" class="${view==='fort'?'active':''}">Fortifications</button></nav></header>`}
function army(){for(let c of state.corps)for(let f of c.formations){if(isInf(f))normalizeFormation(f);if(c.nation==='Allemagne'&&deSpec(f))deApply(f);if(['scout','horseScout'].includes(f.kind)){let src=scoutSources(f).find(x=>x.id===f.scoutSource);if(src){f.scoutSource=src.id;f.infType=src.infType;f.exp=src.exp;f.morale=src.morale}}}return `<section class="panel"><h2>Paramètres de bataille</h2><div class="grid">${field('Nom de la liste','listName',state.name)}<label>Front${sel('front',['EST','OUEST','AFRIQUE','ITALIE','FINLANDE'],state.front)}</label><label>Période${sel('period',PERIOD,state.period)}</label>${field('Année','year',state.year,'number','min="1939" max="1947"')}<label>Saison${sel('season',['','Printemps','Été','Automne','Hiver'].map(x=>[x,x||'Non précisée']),state.season)}</label>${field('Budget global (pts)','budget',state.budget,'number','min="1"')}</div></section>${summary()}<section class="panel"><div class="line"><h2>Corps d’armée</h2>${state.corps.length<2?'<button data-action="addCorps">+ Corps auxiliaire</button>':''}</div>${state.corps.map((c,i)=>corpMarkup(c,i)).join('')}</section><section class="panel"><h2>Contrôles de composition</h2>${warnings().length?warnings().map(x=>`<p class="warning">⚠ ${E(x)}</p>`).join(''):'<p class="good">Aucun avertissement détecté par les contrôles disponibles. Vérifier les exceptions OdB non structurées.</p>'}</section>${deG4Markup()}${saveMarkup()}`}
KINDS.art='Formation d’Appui Feu';KINDS.at='Formation anti-char';KINDS.aa='Formation anti-aérienne';
const FORM_GROUPS={'Infanterie et cavalerie':['inf','reserve','genie','cav','scout','horseScout','sniper'],'Formation blindée':['light','medium','heavy'],'Canons d’assaut et chasseurs de chars':['assault','td'],'Reconnaissance':['recon'],'Formations de canons':['art','at','aa','offtable'],'Aviation':['air'],'Logistique':['transport']};
const DE_INF_FORMATIONS=[
 {name:'Compagnie de Grenadiers',kind:'inf',from:1939,to:1945,reduce:1940},
 {name:'Compagnie de Gebirgsjäger',kind:'inf',from:1939,to:1945,reduce:1940},
 {name:'Compagnie de Panzergrenadiers',kind:'inf',from:1939,to:1945,reduce:1939},
 {name:'Compagnie de Pionniers',kind:'genie',from:1939,to:1945,reduce:1939},
 {name:'Compagnie de Fallschirmjäger',kind:'inf',from:1939,to:1945,reduce:1942},
 {name:'Section d’éclaireurs',kind:'scout',from:1939,to:1945},
 {name:'Section de chasseurs de char',kind:'inf',from:1943,to:1945,section:true},
 {name:'Compagnie de Volksgrenadiers',kind:'inf',from:1944,to:1945,reduce:1944},
 {name:'Détachement de Volkstürm',kind:'inf',from:1945,to:1945,section:true,west:true},
 {name:'Section d’éclaireurs à cheval',kind:'horseScout',from:1939,to:1945}
];
function deEnd(y){return Number(y)===1945?1947:Number(y)}
function deYear(){return Math.min(1945,Number(state.year)||1945)}
function deInfAllowed(){return DE_INF_FORMATIONS.filter(x=>state.year>=x.from&&state.year<=deEnd(x.to)&&(!x.west||state.front==='OUEST')).filter(x=>x.name!=='Détachement de Volkstürm')}
function deInfSelected(c){return deInfAllowed().find(x=>x.name===c.nextGermanInf)}
function deSpec(f){return DE_INF_FORMATIONS.find(x=>x.name===f.germanOdbFormation)}
function deHostOptions(f){let c=corps(f.corpId);return (c?.formations||[]).filter(x=>x.id!==f.id&&['inf','genie'].includes(x.kind)&&x.germanOdbFormation!=='Détachement de Volkstürm')}
function deRulesMarkup(f){let sp=deSpec(f);if(!sp)return '';let y=deYear(), options=[];
 if(sp.reduce)options.push(`<label>Structure${sel('companySize',[["standard","Compagnie complète · 3 sections"],...(y>=sp.reduce?[["reduite","Compagnie réduite · 2 sections"]]:[])],f.size||'standard',`data-f="${f.id}"`)}</label>`);
 if(sp.name.includes('Grenadiers')&&!sp.name.includes('Volks'))options.push(`<label>Variante de section${sel('deVariant',[["","Standard"],...(y<=1941?[["quatre","4 groupes par section"]]:[]),...(y>=1944?[["assaut","Section d’Assaut"]]:[])],f.deVariant||'',`data-f="${f.id}"`)}</label>`);
 if(sp.name.includes('Gebirgsjäger'))options.push(`<label>Variante de section${sel('deVariant',[["","Standard"],...(y<=1941?[["quatre","4 groupes par section"]]:[]),...(y>=1942?[["lourde","Section Lourde"]]:[])],f.deVariant||'',`data-f="${f.id}"`)}</label>`);
 if(sp.name.includes('Panzergrenadiers'))options.push(chk('Convertir une section en Pionniers (max. 1)','dePioneer',!!f.dePioneer,`data-f="${f.id}"`));
 if(sp.name.includes('Fallschirmjäger'))options.push(`${y<=1941?'Compagnie d’Assaut':'Compagnie Lourde'}${y<=1941?' · Aéroportée possible':''}${y>=1944?' · Troupes de choc possibles':''}`,chk('Section de Pionniers (1942–1945)','dePioneer',!!f.dePioneer,`data-f="${f.id}" ${y<1942?'disabled':''}`),...(y<=1941?[chk('Aéroportée','deAirborne',!!f.deAirborne,`data-f="${f.id}"`)]:[]),...(y>=1944?[chk('Troupes de choc','deShock',!!f.deShock,`data-f="${f.id}"`)]:[]));
 if(sp.name.includes('Volksgrenadiers'))options.push(chk('Une section de Ligne','deLine',!!f.deLine,`data-f="${f.id}"`));
 if(sp.name.includes('Pionniers'))options.push(`<label>Organisation${sel('dePioneerMode',[["company","Compagnie"],["attached","Section rattachée à une formation"]],f.dePioneerMode||'company',`data-f="${f.id}"`)}</label>`);
 if(sp.name.includes('Pionniers')&&f.dePioneerMode==='attached')options.push(`<label>Formation hôte${sel('deHost',[['','Sélectionner une formation hôte'],...deHostOptions(f).map(x=>[x.id,x.name])],f.deHost||'',`data-f="${f.id}"`)}</label>`);
 if(sp.name.includes('éclaireurs')&&!sp.name.includes('cheval'))options.push(`<label>Catégorie${sel('deScoutType',[["Ligne","Ligne"],["PM","PM"],...(y>=1943?[["Lourde","Lourde"]]:[]),...(y>=1944?[["Assaut","Assaut"]]:[])],f.deScoutType||'Ligne',`data-f="${f.id}"`)}</label>`);
 if(sp.name.includes('cheval'))options.push(`<label>Effectif${sel('deHorseCount',[[2,'2 unités'],[3,'3 unités'],...(y<=1943?[[4,'4 unités (+1)']]:[])],f.sections?.[0]?.units?.length||2,`data-f="${f.id}"`)}</label>`);
 if(sp.name.includes('chasseurs de char'))options.push('Formation d’infanterie antichar distincte des chasseurs de chars blindés.');
 return `<div class="unit"><h4>Structure validée — OdB Allemagne / Groupe 1</h4><div class="grid">${options.join('')}</div></div>`;
}
function deApply(f){let sp=deSpec(f);if(!sp)return;let y=deYear();
 if(sp.section||sp.kind==='scout'||sp.kind==='horseScout'||f.dePioneerMode==='attached'){f.sections=f.sections.slice(0,1);if(!f.sections.length)f.sections=[mkSection(f.infType||'Ligne',sp.kind==='genie')];}
 if(sp.name.includes('Fallschirmjäger')){f.infType=y<=1941?'Assaut':'Lourde';f.sections.forEach(x=>{if(!x.genie){x.type=f.infType;x.units.forEach(u=>u.type=f.infType)}})};if(y<1942)f.dePioneer=false;
 if(sp.name.includes('Volksgrenadiers')&&f.deLine&&f.sections[0]){f.sections[0].type='Ligne';f.sections[0].units.forEach(u=>u.type='Ligne')}
 if(sp.name.includes('Panzergrenadiers')||sp.name.includes('Fallschirmjäger'))f.sections.forEach((x,i)=>{x.genie=!!f.dePioneer&&i===0});
 if(sp.name.includes('éclaireurs')&&!sp.name.includes('cheval')&&f.sections[0]){f.infType=f.deScoutType||'Ligne';f.sections[0].type=f.infType;f.sections[0].units.forEach(u=>u.type=f.infType)}
 if(sp.name.includes('cheval')){let n=Math.min(y<=1943?4:3,Math.max(2,Number(f.deHorseCount)||2));let sec=f.sections[0];while(sec.units.length<n)sec.units.push({...mkUnit(),type:sec.type});sec.units=sec.units.slice(0,n)}
 if(sp.name.includes('Grenadiers')&&!sp.name.includes('Volks')||sp.name.includes('Gebirgsjäger')){if(f.deVariant==='quatre'&&y<=1941)f.sections.forEach(x=>{while(x.units.length<4)x.units.push({...mkUnit(),type:x.type})});if(f.deVariant==='assaut'&&y>=1944)f.sections.forEach(x=>{x.type='Assaut';x.units.forEach(u=>u.type='Assaut')});if(f.deVariant==='lourde'&&y>=1942)f.sections.forEach(x=>{x.type='Lourde';x.units.forEach(u=>u.type='Lourde')})}
}
function corpMarkup(c,i){let d=DOC[c.doctrine]||DOC[0],p=c.formations.reduce((n,f)=>n+(formationPrice(f)||0),0);let group=c.nextGroup||'Infanterie et cavalerie',allowed=(FORM_GROUPS[group]||FORM_GROUPS['Infanterie et cavalerie']).filter(k=>(k!=='sniper'||c.nation==='URSS')&&(c.nation!=='Allemagne'||!['cav','reserve'].includes(k)));if(c.nation==='Allemagne'&&group==='Infanterie et cavalerie')allowed=[...new Set(deInfAllowed().map(x=>x.kind))];if(!allowed.includes(c.nextKind))c.nextKind=allowed[0]||'';return `<article class="corp"><div class="line"><h3>${i===0?'Corps principal':'Corps auxiliaire'} <span class="pill">${money(p)}</span></h3>${i?`<button class="danger" data-action="removeCorps" data-c="${c.id}">Retirer</button>`:''}</div><div class="grid"><label>Nation${sel('nation',['Allemagne','URSS'],c.nation,`data-c="${c.id}"`)}</label><label>Groupe d’armées${sel('group',[['standard','Groupe standard (provisoire)'],['reserve','Groupe de Réserve (provisoire)']],c.group,`data-c="${c.id}"`)}</label><label>Structure / doctrine${sel('doctrine',DOC.map((x,j)=>[j,x.name]),c.doctrine,`data-c="${c.id}"`)}</label></div><p class="muted">${E(d.note==='-'?'':d.note)} · Limites : ${Object.entries(d.limits).map(([k,v])=>`${KINDS[k]||k} ${v}`).join(' · ')}</p><div class="formation-picker"><h4>Ajouter une formation selon la structure</h4><div class="grid"><label>1. Catégorie${sel('newGroup',Object.keys(FORM_GROUPS),group,`data-c="${c.id}"`)}</label><label>2. Type de formation${c.nation==='Allemagne'&&group==='Infanterie et cavalerie'?sel('newGermanInf',deInfAllowed().map(x=>[x.name,x.name]),deInfSelected(c)?.name||deInfAllowed()[0]?.name||'',`data-c="${c.id}"`):sel('newKind',allowed.map(k=>[k,KINDS[k]]),c.nextKind,`data-c="${c.id}"`)}</label></div><button data-action="addFormation" data-c="${c.id}">+ Ajouter cette formation</button></div><h4>Mes formations (${c.formations.length})</h4>${c.formations.length?c.formations.map(f=>`<details class="formation-shell" ${f.id===editId?'open':''}><summary>${E(f.name)} · ${money(formationPrice(f))} ${rarity(f)?'· '+('*'.repeat(rarity(f))):''}</summary>${formationMarkup(f)}</details>`).join(''):'<p class="muted">Choisissez une catégorie et ajoutez votre première formation.</p>'}</article>`}
function formationMarkup(f){let inf=isInf(f),choices=candidates(f),lim=limits(f),rare=rarity(f);return `<article class="formation"><div class="line"><h3>${E(f.name)} <span class="pill">${money(formationPrice(f))}</span>${rare?` <span class="rare">${'*'.repeat(rare)}</span>`:''}</h3><div class="toolbar"><button class="small" data-action="duplicateFormation" data-f="${f.id}">Dupliquer la formation</button><button class="danger small" data-action="removeFormation" data-f="${f.id}">Supprimer</button></div></div><div class="grid">${field('Nom de formation','formationName',f.name,'text',`data-f="${f.id}"`)}<label>Expérience${sel('formationExp',EXPS.filter(x=>x!=='As'||isEligibleAs(f)),f.exp,`data-f="${f.id}"`)}</label><label>Moral${sel('formationMorale',MORALES,f.morale,`data-f="${f.id}"`)}</label>${chk('Oscillant','formationOsc',f.osc,`data-f="${f.id}"`)}${chk('Fanatique','formationFan',f.fan,`data-f="${f.id}"`)}</div><p class="muted">Valeurs héritées par chaque unité, sauf exception individuelle. ${lim?`Effectif de référence : ${lim[0]}–${lim[1]}.`:''}</p>${deRulesMarkup(f)}${corps(f.corpId)?.nation==='Allemagne'&&state.year>=1945&&state.year<=1947&&state.front==='OUEST'&&['inf','genie'].includes(f.kind)&&!f.name.includes('Volkstürm')?`<button class="small" data-action="addVolksturm" data-f="${f.id}">+ Renfort : section de Volkstürm</button>`:''}${inf?`<p class="muted">Panzerfaust : ${panzerfaustCount(f)} / ${panzerfaustLimit(f)}</p>`:''}${f.kind==='offtable'?offtableMarkup(f):inf?infMarkupV4(f):`${f.kind==='air'?`<label>Catégorie aérienne${sel('airCategory',['Chasse','Attaque','Bombardier'],f.airCategory||'Chasse',`data-f="${f.id}"`)}</label>`:''}${modelListMarkup(f,choices)}`}${inf?'':supportMarkup(f)}${formationIssues(f).length?`<div class="unit"><b>Contrôles de formation</b>${formationIssues(f).map(t=>`<p class="warning">⚠ ${E(t)}</p>`).join('')}</div>`:''}${f.forts.length?`<p>Fortifications intégrées : ${f.forts.map(E).join(', ')}</p>`:''}</article>`}
function offtableMarkup(f){return `<p class="muted">Selon « Budget détaillé » : demi-batterie = 3 × coût complet par pièce ; batterie = 6 × coût complet par pièce. L’OBS est gratuit. Le coût complet d’une pièce comprend PdF, AC, taille, vitesse, ouvert/fermé et blindage.</p><div class="grid"><label>Format${sel('batterySize',[['half','Demi-batterie · 3 pièces'],['full','Batterie complète · 6 pièces']],f.batterySize||'half',`data-f="${f.id}"`)}</label>${field('Coût complet d’une pièce (budget détaillé)','offtableUnitPrice',f.offtableUnitPrice??'','number',`min="0" step="0.01" data-f="${f.id}"`)}</div><p><b>Total : ${money(artilleryOfftablePrice(f))}</b> · OBS inclus, gratuit</p>`}
// Groupe 3 — unités structurées, QG, sections, renforts et transports.
const INF_TYPES=['Servants / équipe légère','Milice','Réserve','Ligne','Lourde','Assaut','PM / automatiques','Commissaire politique'];
const ENGINEER_RE=/charge explosive|mine magn[eé]tique|goliath|borgward|lance-flammes/i;
const mkSection=(type='Ligne',genie=false)=>({id:id(),type,genie,units:Array.from({length:3},()=>({...mkUnit(),type})),support:[],transportId:'',sidecar:''});
function initializeFormation(f){if(f.kind==='reserve'){f.reserveUnits=Array.from({length:4},()=>({...mkUnit(),type:'Réserve'}));f.infType='Réserve'}else if(['scout','horseScout'].includes(f.kind)){f.sections=[mkSection('Ligne')];if(f.kind==='horseScout')f.sections[0].units.pop()}else if(f.kind==='sniper'){f.sniperCount=2}else if(['inf','cav','genie'].includes(f.kind)){f.sections=Array.from({length:3},()=>mkSection('Ligne',f.kind==='genie'));f.engineer=f.kind==='genie'}f.hq={...mkUnit(),type:f.infType,command:true};}
function normalizeFormation(f){if(!isInf(f))return;if(!f.hq)f.hq={...mkUnit(),type:f.infType||'Ligne',command:true};if(!f.infType)f.infType=f.kind==='reserve'?'Réserve':'Ligne';if(!Array.isArray(f.sections))f.sections=[];if(!Array.isArray(f.reserveUnits))f.reserveUnits=[];if(f.kind==='reserve'&&!f.reserveUnits.length)f.reserveUnits=Array.from({length:4},()=>({...mkUnit(),type:f.infType}));if(['inf','cav','genie'].includes(f.kind)&&!f.sections.length){f.sections=Array.from({length:3},()=>mkSection(f.infType,f.kind==='genie'));if(f.units?.length){f.sections[0].units=f.units.map(u=>({...u,options:u.options||[]})).slice(0,4);f.units=[]}}if(['scout','horseScout'].includes(f.kind)&&!f.sections.length){f.sections=[mkSection(f.infType)];if(f.kind==='horseScout')f.sections[0].units.pop();}if(f.kind==='sniper'&&!f.sniperCount)f.sniperCount=2;}
function infTable(f){return ['cav','horseScout'].includes(f.kind)?B.cav:B.inf}
function infOptTable(f){return ['cav','horseScout'].includes(f.kind)?B.cavOptions:B.infOptions}
function infCost(f,u,command=false){const t=infTable(f),o=infOptTable(f);let n=(t[u.type]||0)+(command?(t.Commandement||0):0);for(let k of (u.options||[])){if((!ENGINEER_RE.test(k)||u.genie||f.engineer||f.kind==='genie')&&k!=='Reco'&&k!=='Indépendantes')n+=o[k]||0}return adjust(n,u.exp||f.exp,u.morale||f.morale,u.osc||f.osc,u.fan||f.fan)}
function transportPrice(tid,sidecar=''){if(!tid)return 0;let x=item(tid);if(!x)return null;let p=x.costs?.[state.period];if(p==null)return null;return p+(x.id==='universal-motos'?({standard:3,mmg:5,hmg:7}[sidecar]||0):0)}
function infantryFormationPrice(f){normalizeFormation(f);if(['scout','horseScout'].includes(f.kind)){let src=scoutSources(f).find(x=>x.id===f.scoutSource);if(src){f.scoutSource=src.id;f.infType=src.infType;f.exp=src.exp;f.morale=src.morale;f.sections[0].type=src.infType;for(let u of f.sections[0].units){u.type=src.infType;u.exp=null;u.morale=null}}}let n=baseFormation(f);if(f.kind==='reserve'){
 n+=infCost(f,f.hq,true);for(let u of f.reserveUnits)n+=infCost(f,u);if(f.reinforceEngineer){{let sp=sectionPrice(f,f.engineerSection||mkSection('Ligne',true));if(sp==null)return null;n+=sp}}}
 else if(f.kind==='sniper'){let hq={...f.hq,type:f.sniperHQ==='Sniper'?'Servants / équipe légère':f.sniperHQ};n+=infCost(f,hq,true);if(f.sniperHQ==='Sniper')n+=B.support.Sniper||0;n+=(f.sniperCount||2)*(B.support.Sniper||0)}
 else{if(!['scout','horseScout'].includes(f.kind))n+=infCost(f,f.hq,true);for(let sec of f.sections){let sp=sectionPrice(f,sec);if(sp==null)return null;n+=sp}}
 const hqTr=['scout','horseScout','sniper'].includes(f.kind)?0:transportPrice(f.hq.transportId,f.hq.sidecar);if(hqTr==null)return null;n+=hqTr*Math.max(1,Number(f.hq.transportCount)||1);
 for(let m of f.models){let p=modelPrice(f,m);if(p==null)return null;n+=p}
 for(let k of f.support||[])n+=B.support[k]||0;
 return n;
}
function sectionPrice(f,sec){let n=0;for(let u of sec.units){n+=infCost(f,{...u,genie:sec.genie||f.engineer})}let tr=transportPrice(sec.transportId,sec.sidecar);if(tr==null)return null;n+=tr*Math.max(1,Number(sec.transportCount)||1);for(let k of sec.support||[])n+=B.support[k]||0;return n}
function escortAllowed(f){const nation=corps(f.corpId)?.nation;if(nation==='URSS')return state.year>=1941&&['light','medium','heavy','assault','td'].includes(f.kind);return nation==='Allemagne'&&state.year>=1943&&state.front==='EST'&&['medium','heavy','assault'].includes(f.kind)}
function escortPrice(f,m){let n=m.escort==='pm'?10:m.escort==='assault'?15:0;if(!n)return 0;for(let k of m.escortOptions||[]){if(k!=='Reco'&&k!=='Indépendantes'&&!ENGINEER_RE.test(k))n+=B.infOptions[k]||0}return adjust(n,m.escortExp||f.exp,m.escortMorale||f.morale,false,false)}
function escortMarkup(f,m){if(!escortAllowed(f))return '';let sov=corps(f.corpId)?.nation==='URSS',v=m.escort||'';return `<details><summary>${sov?'Tankodesantniki':'Escorte de char'} ${v?'— '+money(escortPrice(f,m)):''}</summary><div class="grid"><label>Unité rattachée${sel('escortType',sov?[['','Aucune'],['pm','PM · 10 pts']]:[['','Aucune'],['pm','PM · 10 pts'],['assault','Assaut · 15 pts']],v,`data-f="${f.id}" data-m="${m.id}"`)}</label>${v?`<label>Expérience${sel('escortExp',EXPS.filter(x=>x!=='As'),m.escortExp||f.exp,`data-f="${f.id}" data-m="${m.id}"`)}</label><label>Moral${sel('escortMorale',MORALES,m.escortMorale||f.morale,`data-f="${f.id}" data-m="${m.id}"`)}</label>`:''}</div>${v?`<div class="options">${Object.entries(B.infOptions).filter(([k])=>!['Reco','Indépendantes','Commando','Troupe Coloniale','Résistant/partisan'].includes(k)&&!ENGINEER_RE.test(k)).map(([k,p])=>chk(`${E(k)} (+${money(p)})`,'escortOption',(m.escortOptions||[]).includes(k),`data-f="${f.id}" data-m="${m.id}" data-value="${E(k)}"`)).join('')}</div><p class="muted">Commandement assuré par la formation blindée · ni Indépendant ni Reco · 1 unité par char.</p>`:''}</details>`}
// Groupe 2 : supports d'infanterie allemands, sans tarifs supposés.
const DE_G2={
 'Cie Grenadiers':[['MMG',1939,1945,2],['HMG',1939,1945,2],['Mortier léger',1939,1943,1],['Mortier moyen',1942,1945,1],['Fusil antichar',1939,1945,1,'obsolete42'],['Panzerschreck',1942,1945,1]],
 'Cie de Gebirgsjäger':[['MMG',1939,1945,2],['HMG',1939,1945,2],['Fusil antichar',1939,1945,1,'obsolete42'],['Panzerschreck',1942,1945,1]],
 'Cie de Pzgrenadiers':[['Lance-flammes',1939,1945,1],['HMG',1939,1945,2],['Mortier moyen',1942,1945,1],['Fusil antichar',1939,1945,1,'obsolete42'],['Panzerschreck',1942,1945,2]],
 'Cie de Pionniers':[['MMG',1941,1945,1],['Mortier moyen',1939,1945,1],['Lance-flammes',1939,1945,1]],
 'Cie de Fallschirmjäger':[['MMG',1942,1945,1],['Mortier moyen',1942,1945,1],['Panzerschreck',1942,1945,1],['Lance-flammes',1942,1945,1]],
 'Section d’éclaireurs':[],
 'Section de chasseurs de char':[],
 'Cie de Volksgrenadiers':[['MMG',1944,1945,1],['HMG',1944,1945,1]],
 'Détachement de Volkstürm':[],
 'Section d’éclaireurs Cavalerie':[['MMG',1939,1945,1]]
};
const DE_G2_UNIT={
 'Cie Grenadiers':[['Panzerfaust',1942,1945]],
 'Cie de Gebirgsjäger':[['Panzerfaust',1942,1945]],
 'Cie de Pzgrenadiers':[['Panzerfaust',1942,1945]],
 'Cie de Pionniers':[['Charges explosives',1939,1945],['Grenades fumigènes',1939,1945]],
 'Cie de Fallschirmjäger':[['Panzerfaust',1942,1945],['Charges explosives',1942,1945]],
 'Section d’éclaireurs':[['Panzerfaust',1943,1945],['Optique IR',1945,1945]],
 'Section de chasseurs de char':[['Charges explosives',1943,1945],['Panzerfaust',1943,1945]],
 'Cie de Volksgrenadiers':[['Panzerfaust',1944,1945],['Vélos',1945,1945]],
 'Détachement de Volkstürm':[['Panzerfaust',1945,1945],['Vélos',1945,1945]]
};
function deG2(f){return corps(f.corpId)?.nation==='Allemagne'&&Object.prototype.hasOwnProperty.call(DE_G2,f.germanOdbFormation)}
function deG2SupportRows(f){return (DE_G2[f.germanOdbFormation]||[]).filter(r=>state.year>=r[1]&&state.year<=deEnd(r[2]))}
function deG2UnitAllowed(f,k){let rows=DE_G2_UNIT[f.germanOdbFormation]||[];return rows.some(r=>r[0]===k&&state.year>=r[1]&&state.year<=deEnd(r[2]))}
function deG2SupportCount(f,k){return Number((f.deG2Supports||{})[k]||0)}
function deG2SupportPrice(f){let sum=0;for(let [k,n] of Object.entries(f.deG2Supports||{})){if(!n)continue;if(B.support[k]===undefined)return null;sum+=Number(n)*B.support[k]}return sum}
function deG2SupportMarkup(f){let rows=deG2SupportRows(f);return `<details open><summary>Supports allemands — OdB Groupe 2</summary><div class="grid">${rows.map(([k,from,to,max,obsolete])=>{let price=B.support[k],n=deG2SupportCount(f,k),mg=k==='MMG'||k==='HMG',maxAllowed=mg&&f.germanOdbFormation==='Cie Grenadiers'?Math.min(max,2-deG2SupportCount(f,k==='MMG'?'HMG':'MMG')):max;return `<label>${E(k)} ${price===undefined?'— tarif à confirmer':'('+money(price)+' / support)'}${obsolete&&state.year>=1942?' — Réserve, * (obsolète)':''}${sel('deG2SupportCount',Array.from({length:maxAllowed+1},(_,i)=>[i,String(i)]),Math.min(n,maxAllowed),`data-f="${f.id}" data-value="${E(k)}"`)}</label>`}).join('')}</div><p class="muted">Les supports dont le tarif manque restent signalés, jamais comptés gratuitement. Grenadiers : MMG + HMG ≤ 2.</p></details>`}
function deG2Issues(f){let out=[];if(!deG2(f))return out;let allowed=deG2SupportRows(f);for(let [k,n] of Object.entries(f.deG2Supports||{})){if(!n)continue;let row=allowed.find(r=>r[0]===k);if(!row)out.push('Support allemand indisponible en '+state.year+' : '+k);else if(n>row[3])out.push('Quota dépassé : '+k);if(B.support[k]===undefined)out.push('Tarif manquant pour '+k+' : budget non calculable')}if(f.germanOdbFormation==='Cie Grenadiers'&&deG2SupportCount(f,'MMG')+deG2SupportCount(f,'HMG')>2)out.push('Grenadiers : maximum deux supports MG additionnels, MMG et/ou HMG');for(let k of f.support||[])out.push('Ancien support QG à migrer vers les supports OdB : '+k);for(let sec of f.sections||[]){for(let k of sec.support||[])out.push('Ancien support de section à migrer vers les supports OdB : '+k);for(let u of sec.units||[])for(let k of u.options||[]){if(/panzerfaust|charges explosives|grenades fumig[eè]nes|optique ir|v[eé]los/i.test(k)){let canonical=/panzerfaust/i.test(k)?'Panzerfaust':/charges explosives/i.test(k)?'Charges explosives':/grenades fumig/i.test(k)?'Grenades fumigènes':/optique ir/i.test(k)?'Optique IR':'Vélos';if(!deG2UnitAllowed(f,canonical))out.push('Équipement hors OdB/période : '+k)}}}return [...new Set(out)]}
function sectionSupportMarkup(f,sec){if(deG2(f))return '<p class="muted">Supports allemands : sélection au niveau de la formation selon l’OdB.</p>';return `<details><summary>Supports de section (${(sec.support||[]).length})</summary><div class="options">${Object.entries(B.support).filter(([k])=>k!=='Observateur supplémentaire'&&(!ENGINEER_RE.test(k)||sec.genie||f.engineer)).map(([k,p])=>chk(`${E(k)} (${money(p)})`,'sectionSupport',(sec.support||[]).includes(k),`data-f="${f.id}" data-sec="${sec.id}" data-value="${E(k)}"`)).join('')}</div></details>`}
function transportArmored(x){return !/non blind[eé]|sans blindage/i.test(String(x.armor||''))&&(/blind[eé]/i.test(String(x.armor||''))||/half.track|semi.chenill[eé]|sdkfz 25[01]|m3 half/i.test(String(x.name||'')))}
function transportSelector(f,action,tid,sidecar,extra){let list=all().filter(x=>x.kind==='transport'&&available(x,corps(f.corpId)));const type=String(f.transportClass||'all');if(type!=='all')list=list.filter(x=>transportArmored(x)===(type==='armored'));return `<div class="grid"><label>Catégorie de transport${sel('transportClass',[['all','Tous'],['armored','Blindé'],['unarmored','Non blindé']],f.transportClass||'all',`data-f="${f.id}"`)}</label><label>Transport${sel(action,[['','Sans transport'],...list.map(x=>[x.id,`${x.name} · ${money(x.costs[state.period])}`])],tid||'',extra)}</label>${tid==='universal-motos'?`<label>Side-car${sel(action+'Sidecar',[['','Aucun'],['standard','Standard (+3) Transport (1) + ST'],['mmg','MMG (+5)'],['hmg','HMG (+7)']],sidecar||'',extra)}</label>`:''}</div>`}
function infantryUnitMarkup(f,u,sec){let table=infTable(f),extras=infOptTable(f),eng=!!(f.engineer||sec?.genie);return `<div class="unit"><div class="line">${['scout','horseScout'].includes(f.kind)&&u!==f.hq?`<span>Type commun : ${E(f.infType)}</span>`:`<label>Type${sel('g3UnitType',Object.keys(table).filter(k=>k!=='Commandement'),u.type,`data-f="${f.id}" data-u="${u.id}"`)}</label>`}<b>${money(infCost(f,{...u,genie:eng}))}</b>${sec||f.kind==='reserve'?`<button class="small" data-action="duplicateInfUnit" data-f="${f.id}" data-u="${u.id}" data-sec="${sec?.id||''}">Dupliquer</button>`:''}</div><div class="grid"><label>Expérience${sel('g3UnitExp',[['','Formation'],...EXPS.filter(x=>x!=='As').map(x=>[x,x])],u.exp||'',`data-f="${f.id}" data-u="${u.id}"`)}</label><label>Moral${sel('g3UnitMorale',[['','Formation'],...MORALES.map(x=>[x,x])],u.morale||'',`data-f="${f.id}" data-u="${u.id}"`)}</label></div><details><summary>Traits et équipements (${(u.options||[]).length})</summary><div class="grid">${infantryOptionsUI(f,u,sec)}</div></details></div>`}
function sectionMarkup(f,sec,i){return `<div class="unit"><div class="line"><h4>Section ${i+1} — ${E(sec.type)}</h4><b>${money(sectionPrice(f,sec))}</b><button class="small" data-action="duplicateSection" data-f="${f.id}" data-sec="${sec.id}">Dupliquer la section</button></div><div class="grid">${['scout','horseScout'].includes(f.kind)?`<span>Type lié : ${E(f.infType)}</span>`:`<label>Type de la section${sel('sectionType',Object.keys(infTable(f)).filter(k=>k!=='Commandement'),sec.type,`data-f="${f.id}" data-sec="${sec.id}"`)}</label>`}${['scout','horseScout'].includes(f.kind)?'':!f.engineer?chk('Section Génie','sectionEngineer',sec.genie,`data-f="${f.id}" data-sec="${sec.id}" ${!sec.genie&&f.sections.some(x=>x.genie)?'disabled':''}`):'<span>Compagnie Génie</span>'}</div>${sec.units.map(u=>infantryUnitMarkup(f,u,sec)).join('')}${sec.units.length<4?`<button class="small" data-action="sectionAddUnit" data-f="${f.id}" data-sec="${sec.id}">+ Unité</button>`:''}${sec.units.length>(f.kind==='horseScout'?2:3)?`<button class="small danger" data-action="sectionRemoveUnit" data-f="${f.id}" data-sec="${sec.id}">Retirer une unité</button>`:''}${sectionSupportMarkup(f,sec)}${transportSelector(f,'sectionTransport',sec.transportId,sec.sidecar,`data-f="${f.id}" data-sec="${sec.id}"`)}${sec.transportId?`<label>Nombre de transports affectés à la section${sel('sectionTransportCount',Array.from({length:12},(_,i)=>[i+1,String(i+1)]),sec.transportCount||1,`data-f="${f.id}" data-sec="${sec.id}"`)}</label>`:''}</div>`}
function scoutSources(f){return corps(f.corpId).formations.filter(g=>g.id!==f.id&&(f.kind==='horseScout'?g.kind==='cav':['inf','genie','reserve'].includes(g.kind)))}
function infMarkupV4(f){normalizeFormation(f);let isReserve=f.kind==='reserve',isScout=['scout','horseScout'].includes(f.kind),isSniper=f.kind==='sniper',sources=isScout?scoutSources(f):[];if(isScout){let src=sources.find(x=>x.id===f.scoutSource);if(src){f.scoutSource=src.id;f.infType=src.infType;f.exp=src.exp;f.morale=src.morale}if(f.sections.length!==1)f.sections=[f.sections[0]||mkSection(f.infType)];f.sections[0].type=f.infType;for(let u of f.sections[0].units){u.type=f.infType;u.exp=null;u.morale=null}}
 let top=isSniper?`<h4>Section de snipers soviétiques</h4><div class="grid"><label>QG${sel('sniperHQ',[['Réserve','Réserve'],['Ligne','Ligne'],['PM / automatiques','PM'],['Sniper','Support Sniper']],f.sniperHQ||'Réserve',`data-f="${f.id}"`)}</label><label>Supports Sniper${sel('sniperCount',[[2,'2 supports indépendants'],[3,'3 supports indépendants']],f.sniperCount||2,`data-f="${f.id}"`)}</label></div><label>Expérience QG${sel('g3UnitExp',[['','Formation'],...EXPS.filter(x=>x!=='As').map(x=>[x,x])],f.hq.exp||'',`data-f="${f.id}" data-u="${f.hq.id}"`)}</label><label>Moral QG${sel('g3UnitMorale',[['','Formation'],...MORALES.map(x=>[x,x])],f.hq.morale||'',`data-f="${f.id}" data-u="${f.hq.id}"`)}</label><p class="muted">Tous les supports Sniper sont indépendants, sans radio.</p>`:isScout?`<h4>${f.kind==='horseScout'?'Section d’éclaireurs à cheval (2 à 4 unités)':'Section d’éclaireurs à pied (3 à 4 unités)'}</h4>${sources.length?`<label>Formation de référence${sel('scoutSource',[['','Aucune — type commun libre'],...sources.map(x=>[x.id,`${x.name} · ${x.infType} · ${x.exp} · ${x.morale}`])],f.scoutSource,`data-f="${f.id}"`)}</label><p class="muted">Si une formation de référence est choisie : type, expérience et moral synchronisés. Sinon, type commun à toutes les unités de la section, hors commandement spécifié.</p><label>Type commun${sel('infType',Object.keys(infTable(f)).filter(k=>k!=='Commandement'),f.infType,`data-f="${f.id}"`)}</label>`:`<label>Type de section${sel('infType',Object.keys(infTable(f)).filter(k=>k!=='Commandement'),f.infType,`data-f="${f.id}"`)}</label>`}`:isReserve?`<h4>Groupe de Réserve : QG + 4 à 8 unités</h4><div class="grid"><label>Type initial${sel('infType',INF_TYPES,f.infType,`data-f="${f.id}"`)}</label>${chk('Renfort Génie (section de 3 à 4 unités)','reinforceEngineer',f.reinforceEngineer,`data-f="${f.id}"`)}</div>`:`<div class="grid"><label>Structure${sel('companySize',[['reduite','Réduite · 2 sections'],['standard','Standard · 3 sections'],['augmentee','Augmentée · 4 sections']],f.size||'standard',`data-f="${f.id}"`)}</label><label>Type initial${sel('infType',INF_TYPES,f.infType,`data-f="${f.id}"`)}</label>${chk('Compagnie entière de Génie','companyEngineer',f.engineer,`data-f="${f.id}"`)}</div>`;
 let hq=isSniper||isScout?'':`<div class="unit"><h4>QG de compagnie</h4>${infantryUnitMarkup(f,f.hq)}${transportSelector(f,'hqTransport',f.hq.transportId,f.hq.sidecar,`data-f="${f.id}"`)}${f.hq.transportId?`<label>Nombre de transports du QG${sel('hqTransportCount',Array.from({length:8},(_,i)=>[i+1,String(i+1)]),f.hq.transportCount||1,`data-f="${f.id}"`)}</label>`:''}<details><summary>Supports rattachés au QG</summary><div class="options">${deG2(f)?'<p>Utiliser le panneau Supports allemands ci-dessous.</p>':Object.entries(B.support).map(([k,p])=>chk(`${E(k)} (${money(p)})`,'support',(f.support||[]).includes(k),`data-f="${f.id}" data-value="${E(k)}"`)).join('')}</div></details></div>`;
 let body=isSniper?'':isReserve?`<div class="subhead"><b>Groupe de Réserve (${f.reserveUnits.length}/8)</b>${f.reserveUnits.length<8?`<button class="small" data-action="reserveAdd" data-f="${f.id}">+ Unité</button>`:''}</div>${f.reserveUnits.map(u=>`<div>${infantryUnitMarkup(f,u)}${f.reserveUnits.length>4?`<button class="small danger" data-action="reserveRemove" data-f="${f.id}" data-u="${u.id}">Retirer</button>`:''}</div>`).join('')}${f.reinforceEngineer?sectionMarkup(f,f.engineerSection||(f.engineerSection=mkSection('Ligne',true)),0):''}`:f.sections.map((sec,i)=>sectionMarkup(f,sec,i)).join('');
 return `<div class="unit">${top}</div>${hq}${body}${deG2(f)?deG2SupportMarkup(f):''}${!isSniper?modelListMarkup(f,candidates(f)):''}`;
}
function findInfUnit(f,uid){return [f.hq,...(f.reserveUnits||[]),...(f.sections||[]).flatMap(s=>s.units),...(f.engineerSection?.units||[])].find(x=>x?.id===uid)}
function findSection(f,sid){return [...(f.sections||[]),f.engineerSection].find(x=>x?.id===sid)}
function infMarkup(f){let table=['cav','horseScout'].includes(f.kind)?B.cav:B.inf,options=['cav','horseScout'].includes(f.kind)?B.cavOptions:B.infOptions;return `<div class="subhead"><b>Unités d’infanterie / cavalerie</b><button class="small" data-action="addUnit" data-f="${f.id}">+ Unité</button></div>${f.units.map(u=>`<div class="unit"><div class="line"><label>Type${sel('unitType',Object.keys(table).filter(k=>!k.toLowerCase().includes('commandement')),u.type,`data-f="${f.id}" data-u="${u.id}"`)}</label><b>${money(unitPrice(f,u))}</b><button class="danger small" data-action="removeUnit" data-f="${f.id}" data-u="${u.id}">Retirer</button></div><div class="grid">${chk('Commandement (+ supplément)','unitCommand',u.command,`data-f="${f.id}" data-u="${u.id}"`)}<label>Expérience${sel('unitExp',[['','Formation'],...EXPS.filter(x=>x!=='As').map(x=>[x,x])],u.exp||'',`data-f="${f.id}" data-u="${u.id}"`)}</label><label>Moral${sel('unitMorale',[['','Formation'],...MORALES.map(x=>[x,x])],u.morale||'',`data-f="${f.id}" data-u="${u.id}"`)}</label><label>Transport facultatif${sel('unitTransport',[['','Sans transport'],...all().filter(x=>x.kind==='transport'&&available(x,corps(f.corpId))).map(x=>[x.id,x.name])],u.transportId||'',`data-f="${f.id}" data-u="${u.id}"`)}</label></div><details><summary>Équipements et compétences</summary><div class="options">${Object.entries(options).filter(([k])=>f.kind==='genie'||!/charge explosive|mine magnétique|goliath|borgward/i.test(k)).map(([k,v])=>chk(`${E(k)} (${money(v)})`,'unitOption',u.options.includes(k),`data-f="${f.id}" data-u="${u.id}" data-value="${E(k)}"`)).join('')}</div></details></div>`).join('')}${modelListMarkup(f,candidates(f))}`}
function modelListMarkup(f,choices){let shown=choices.filter(x=>!search||x.name.toLowerCase().includes(search.toLowerCase())).slice(0,350);return `<div class="subhead"><b>${isInf(f)?'Appuis attachés':'Pièces et véhicules'} (${f.models.length})</b></div>${f.models.map(m=>modelMarkup(f,m)).join('')}<div class="toolbar"><label>Filtre catalogue <input data-action="search" placeholder="Rechercher…" value="${E(search)}"></label><label>Choisir un modèle${sel('catalogChoice',shown.map(x=>[x.id,`${x.name} · ${x.mounting||x.subtype} · ${money(x.costs[state.period])}`]),f.choice||shown[0]?.id||'',`data-f="${f.id}"`)}</label><button data-action="addModel" data-f="${f.id}" ${!shown.length?'disabled':''}>+ Recruter</button></div>${corps(f.corpId)?.nation==='Allemagne'&&f.kind==='heavy'?`<div class="unit"><b>Escorte de Tigre I : Panzer III</b><p class="muted">Escorte Panzer III L/M/N, 1942–1943, maximum 3 ; ne compte pas dans les 1–3 Tigre I.</p>${sel('deEscortChoice',deHeavyEscortCandidates(f).map(x=>[x.id,x.name]),f.deEscortChoice||deHeavyEscortCandidates(f)[0]?.id||'',`data-f="${f.id}"`)}<button data-action="deAddHeavyEscort" data-f="${f.id}">+ Ajouter Panzer III escorte</button></div>`:''}${corps(f.corpId)?.nation==='Allemagne'&&['heavy','assault'].includes(f.kind)?`<div class="unit">${chk('Formation de génie blindé (Tigre I / StuG)','deArmoredEngineer',!!f.deArmoredEngineer,`data-f="${f.id}"`)}<p class="muted">Un Goliath ou Borgward IV par char éligible, coût séparé.</p></div>`:''}${isGun(f)?'<p class="muted">Canon tracté, porté ou automoteur : catégories conservées depuis les OdB. Les tracteurs ne sont proposés qu’aux canons tractés.</p>':''}`}
// Équipements de série : cases cochées et verrouillées, déjà payées dans le prix OdB.
// La colonne « équipement additionnel » est une indication, pas une option de série certaine.
function normEquipment(t){return String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\b1\s*x\s*(mg|hmg)\b/g,'$1').replace(/co[ -]?axiale/g,'coaxiale').replace(/anti[ -]?aerienne/g,'antiaerienne').replace(/fumigenes?/g,'fumigene').replace(/\breco\b/g,'reconnaissance').replace(/\bcoduite double\b|\bconduite double\b/g,'double conduite').replace(/\bpivot\b/g,'pivot').replace(/\bfirecrackers+s?\b/g,'firecracker').replace(/[^a-z0-9+]+/g,' ').trim()}
function equipmentIncluded(x,k){
 // Inspect each separated trait rather than searching the entire string: 'Sans radio'
 // must not activate 'Radio', and 'Sans fumigènes' must not activate smoke launchers.
 const raw=[x.constant,x.traits].filter(v=>v&&v!=='-').join(' ; ');
 const tokens=raw.split(/[;,/]/).map(normEquipment).filter(Boolean);
 const key=normEquipment(k).replace(/^\s*(?:mg|hmg)\s+/,'$&');
 const aliases={
  'lance fumigene':['fumigene','lance fumigene'],
  'reconnaissance':['reconnaissance'],
  'mg coaxiale':['mg coaxiale'], 'mg caisse':['mg caisse'],
  'mg antiaerienne':['mg aa','mg antiaerienne'], 'mg tourelle':['mg tourelle'],
  'hmg coaxiale':['hmg coaxiale'], 'hmg caisse':['hmg caisse'],
  'hmg antiaerienne':['hmg aa','hmg antiaerienne'], 'hmg tourelle':['hmg tourelle'],
  'equipement genie':['equipement de genie','equipement genie'],
  'double conduite':['double conduite'], 'pivot 360':['pivot 360'],
  'plateforme tir':['plateforme de tir','plateforme tir'],
  'optiques mediocres':['mauvaises optiques','mauvaise optique','optiques mediocres'],
  'tir rapide':['cadence tir rapide','tir rapide'],
  'optique ir':['optique ir','viseur ir']
 };
 const keys=aliases[key]||[key];
 return tokens.some(token=>{
   // A negated capability cannot imply a positive one.
   if(/^sans\s/.test(token) && key!=='sans radio')return false;
   if(key==='sans radio')return /^sans\s+radio$/.test(token);
   return keys.some(a=>a&&new RegExp('(?:^|\\s)'+a.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:$|\\s|\\()').test(token));
 });
}
function modelOptionMarkup(x,m,availableOpts,f){
 const nation=corps(f.corpId)?.nation;
 const dedicated=[...(nation==='Allemagne'?['Zimmerit','Optique IR']:[]),...(nation==='USA'?['Stabilisateur']:[])];
 return dedicated.filter(k=>!['Schürzen','Blindage improvisé'].includes(k)&&k in availableOpts&&allowedVehicleOption(x,k)&&!equipmentIncluded(x,k)).map(k=>chk(`${E(k)} (+${money(availableOpts[k])})`,'modelOption',(m.options||[]).includes(k),`data-f="${f.id}" data-m="${m.id}" data-value="${E(k)}"`)).join('')||'<span class="muted">Aucun équipement national optionnel applicable.</span>';
}
function modelMarkup(f,m){let x=item(m.catalogId);if(!x)return `<p class="warning">Référence manquante : ${E(m.catalogId)}</p>`;let tract=x.kind==='gun'&&x.mounting==='tracté',tractors=tractorChoices(x,corps(f.corpId));let availableOpts=isGun(f)?B.gunOptions:B.vehicleOptions;return `<details class="unit vehicle-card"><summary><b>${E(x.name)}</b> · ${money(modelPrice(f,m))} · personnaliser</summary><div class="line"><div><b>${E(x.name)}</b> ${x.rarity?' <span class="rare">'+('*'.repeat(x.rarity))+'</span>':''}<p class="muted">${E(x.subtype)} · ${E(x.mounting)} · ${E(x.weapon)} · ${E(x.armor)} · ${E(x.source)} ligne ${x.sourceRow}</p><p class="muted">Inclus dans le coût OdB : ${E(x.constant||'—')} · Traits : ${E(x.traits||'—')} · Équipement additionnel indiqué : ${E(x.additional||'—')}</p></div><b>${money(modelPrice(f,m))}</b><button class="small" data-action="duplicateModel" data-f="${f.id}" data-m="${m.id}">Dupliquer</button><button class="danger small" data-action="removeModel" data-f="${f.id}" data-m="${m.id}">Retirer</button></div><div class="grid"><label>Expérience${sel('modelExp',[['','Formation'],...EXPS.filter(x=>x!=='As'||isEligibleAs(f)).map(x=>[x,x])],m.exp||'',`data-f="${f.id}" data-m="${m.id}"`)}</label><label>Moral${sel('modelMorale',[['','Formation'],...MORALES.map(x=>[x,x])],m.morale||'',`data-f="${f.id}" data-m="${m.id}"`)}</label>${tract?`<label>Tracteur compatible${sel('tractor',[['','Aucun'],...tractors.map(y=>[y.id,`${y.name} · tracteur ${y.tractorClass}`])],m.tractorId||'',`data-f="${f.id}" data-m="${m.id}"`)}</label>`:''}${state.front==='EST'&&canAdaptTracks(x)?chk('Chenilles adaptées','chenilles',m.chenilles,`data-f="${f.id}" data-m="${m.id}"`):''}</div><details><summary>Équipements optionnels spécifiques à la nation</summary><div class="options">${modelOptionMarkup(x,m,availableOpts,f)}</div></details>${armorExtraMarkup(f,m,x)}${m.deHeavyEscort?'<p class="muted">Panzer III — escorte de Tigre I (hors quota des chars lourds).</p>':''}${deEngineerCarrier(f,x)?`<label>Engin de génie attaché (maximum 1 par char)${sel('deDrone',[['','Aucun'],['goliath','Goliath · '+money(B.infOptions['Goliath (Allemagne)'])],['borgward','Borgward IV · '+money(B.infOptions['Borgward IV'])]],m.deDrone||'',`data-f="${f.id}" data-m="${m.id}"`)}</label>`:''}${x.id==='universal-motos'?`<label>Side-car${sel('sidecar',[['','Sans side-car'],['standard','Standard +3 pts · Transport (1) + ST'],['mmg','MMG +5 pts'],['hmg','HMG +7 pts']],m.sidecar||'',`data-f="${f.id}" data-m="${m.id}"`)}</label>`:''}${(m.options||[]).includes('Équipement génie')?`<div class="unit"><b>Équipement de Génie — Firecracker (4+)</b><p class="muted">Explosifs transportés, non utilisables comme armement du véhicule. Aucun réapprovisionnement.</p><div class="grid"><label>Panzerfaust emportés${sel('engineerPanzerfaust',[[0,'0'],[1,'1'],[2,'2'],[3,'3']],m.engineerPanzerfaust||0,`data-f="${f.id}" data-m="${m.id}"`)}</label><label>Charges explosives emportées${sel('engineerCharges',[[0,'0'],[1,'1'],[2,'2']],m.engineerCharges||0,`data-f="${f.id}" data-m="${m.id}"`)}</label></div></div>`:''}${(m.options||[]).includes('Transport de munitions')?'<p class="muted">Transport de munitions : réapprovisionne les munitions épuisées et le carburant des lance-flammes ; ne donne pas Firecracker.</p>':''}${escortMarkup(f,m)}</div></details>`}
function supportMarkup(f){if(['light','medium','heavy','recon','air','transport'].includes(f.kind))return '';
 if(['assault','td'].includes(f.kind))return `<details><summary>Observateur (OBS)</summary>${chk('OBS rattaché','obs',f.obs,`data-f="${f.id}"`)}${f.obs?`<p class="muted">OBS : ${money(B.support['Observateur supplémentaire']||15)}. Un transport peut être affecté ci-dessous.</p>${transportSelector(f,'obsTransport',f.obsTransportId||'',f.obsSidecar||'',`data-f="${f.id}"`)}`:''}</details>`;
 return `<details><summary>OBS, commandement et supports</summary><div class="options">${isGun(f)?chk('Observateur (OBS)','obs',f.obs,`data-f="${f.id}"`)+chk('Unité de commandement','command',f.command,`data-f="${f.id}"`):''}${Object.entries(B.support).filter(([k])=>!['Grippée','Viseur IR'].includes(k)).map(([k,v])=>chk(`${E(k)} (${money(v)})`,'support',f.support.includes(k),`data-f="${f.id}" data-value="${E(k)}"`)).join('')}</div></details>`}
function saveMarkup(){return `<section class="panel"><h2>Sauvegarder / partager</h2><div class="toolbar"><button data-action="save">Sauvegarder localement</button><button data-action="export">Exporter JSON</button><label class="filebutton">Importer JSON<input id="import" type="file" accept=".json,application/json"></label><button data-action="print">Imprimer / PDF</button><button data-action="reset" class="danger">Nouvelle liste</button></div><p class="muted">Version V0.8.9 — Groupes 1 à 4 validés. Contrôles de conformité disponibles ; restrictions historiques incomplètes signalées.</p></section>`}
function forts(){let total=state.independentForts.reduce((n,k)=>n+(B.fortifications[k]||0),0);return `<section class="panel"><h2>Fortifications indépendantes</h2><p>Cette liste est distincte du budget global et ne nécessite pas de doctrine.</p><div class="grid">${field('Budget dédié','fortBudget',state.fortBudget,'number','min="0"')}<label>Fortification${sel('indFortChoice',Object.entries(B.fortifications).map(([k,v])=>[k,`${k} · ${money(v)}`]),state.fortChoice||Object.keys(B.fortifications)[0])}</label></div><button data-action="addIndFort">+ Ajouter</button><h3>Total : ${money(total)} / ${money(state.fortBudget)}</h3>${state.independentForts.map((x,i)=>`<div class="line unit"><span>${E(x)} — ${money(B.fortifications[x])}</span><button class="small danger" data-action="removeIndFort" data-index="${i}">Retirer</button></div>`).join('')}${saveMarkup()}</section>`}
let draft={kind:'inf',name:'Nouvelle unité',nation:'Allemagne',base:15,exp:'Vétéran',morale:'Vaillant',osc:false,fan:false,as:false,options:[],sourceId:''};
function workshopPrice(){let n=Number(draft.base);if(!Number.isFinite(n))return null;for(let k of draft.options.filter(k=>allowedDraftOption(k)))n+= (B.infOptions[k]??B.cavOptions[k]??B.vehicleOptions[k]??B.gunOptions[k]??0);return adjust(n,draft.exp,draft.morale,draft.osc,draft.fan)}
function workshop(){let options=draft.kind==='inf'?B.infOptions:draft.kind==='cav'?B.cavOptions:draft.kind==='gun'?B.gunOptions:B.vehicleOptions;let sources=all().filter(x=>x.nation===draft.nation&&((draft.kind==='gun'&&x.kind==='gun')||(draft.kind==='armor'&&x.kind==='armor')||(draft.kind==='transport'&&x.kind==='transport')||(draft.kind==='air'&&x.kind==='air')));return `<section class="panel"><h2>Calculateur universel</h2><p>Barèmes fixes du budget actualisé. Le blindage des véhicules existants est conservé : aucun éditeur de blindage. Les créations sont enregistrées comme copies personnelles.</p><div class="grid"><label>Catégorie${sel('draftKind',[['inf','Infanterie'],['cav','Cavalerie'],['armor','Véhicule blindé'],['gun','Canon / artillerie / AA'],['transport','Transport'],['air','Aviation'],['fort','Fortification'],['support','Support']],draft.kind)}</label><label>Nation${sel('draftNation',['Allemagne','URSS'],draft.nation)}</label>${field('Nom','draftName',draft.name)}<label>Charger une unité existante${sel('draftSource',[['','Nouvelle unité'],...sources.map(x=>[x.id,x.name])],draft.sourceId)}</label>${field('Coût de base officiel ou OdB (pts)','draftBase',draft.base,'number','step="0.01"')}<label>Expérience${sel('draftExp',EXPS.filter(x=>x!=='As'||['armor','gun','air'].includes(draft.kind)),draft.exp)}</label><label>Moral${sel('draftMorale',MORALES,draft.morale)}</label>${chk('Oscillant','draftOsc',draft.osc)}${chk('Fanatique','draftFan',draft.fan)}</div><details><summary>Traits et équipements (${draft.options.length})</summary><div class="options">${Object.entries(options).filter(([k])=>allowedDraftOption(k)).map(([k,v])=>chk(`${E(k)} (${money(v)})`,'draftOption',draft.options.includes(k),`data-value="${E(k)}"`)).join('')}</div></details><div class="stats"><div><small>Prix recalculé</small><b>${money(workshopPrice())}</b></div><div><small>Coût de base</small><b>${money(Number(draft.base))}</b></div></div><div class="toolbar"><button data-action="draftSave">Enregistrer dans ma bibliothèque</button><button data-action="draftReset">Nouvelle fiche</button></div><p class="muted">Le calculateur applique les suppléments d’expérience par tranche (0–100 / 101–200 / plus de 200) et le moral du budget. Les caractéristiques techniques des matériels créés doivent être renseignées dans leurs fiches de référence ; les prix ne sont pas extrapolés automatiquement.</p><h3>Bibliothèque personnalisée (${state.custom.length})</h3>${state.custom.map(x=>`<div class="line unit"><span>${E(x.name)} · ${E(x.nation)} · ${money(x.costs?.[state.period])}</span><button data-action="deleteCustom" data-id="${x.id}" class="small danger">Supprimer</button></div>`).join('')}</section>${deG4Markup()}${saveMarkup()}`}
function render(){refreshIndexes();const expanded=[...document.querySelectorAll('#app details')].map((el,i)=>el.open?i:-1).filter(i=>i>=0);document.title='Iron Tide — 12-20mm WW2 Wargame — GitHub V0.9.0';$('app').innerHTML=header()+`<main>${view==='army'?army():forts()}</main>`;const details=document.querySelectorAll('#app details');for(const i of expanded)if(details[i])details[i].open=true;for(const d of document.querySelectorAll('.formation-shell'))if(d.querySelector(`[data-f="${editId}"]`))d.open=true;}
function download(name,content,type){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
