 if(a==='listName')state.name=v;else if(['front','period','season'].includes(a)){state[a]=v;if(a==='period')state.year=PERIOD_END_YEAR[v]||state.year;}else if(['year','budget','fortBudget'].includes(a))state[a]=Number(v);
 else if(a==='nation'){c.nation=v;c.formations=[]}else if(a==='group')c.group=v;else if(a==='doctrine')c.doctrine=Number(v);
